+    char *fn = curlx_convert_tchar_to_UTF8(filebuffer_t);
+    if(fn) {
+      size_t fn_len = strlen(fn);
+      if(fn_len >= sizeof(filebuffer)) {
+        curlx_free(fn);
+        return NULL;
       }
+      curlx_strcopy(filebuffer, sizeof(filebuffer), fn, fn_len);
+      curlx_free(fn);
